#include "language.hpp"
#include <sstream>
int main(int argc,char**argv){int m=stoi(argv[7]);assert(m>=20&&m<=30);load(argv[1],argv[2],argv[3],argv[4]);ifstream co(argv[6]);array<int,52>coord;for(int&x:coord)co>>x;ifstream profiles(argv[5]);string line;int number=0;while(getline(profiles,line)){istringstream in(line);int ix,restart;float prof;string h,key;in>>ix>>restart>>prof>>h>>key;replace(h.begin(),h.end(),',',' ');replace(key.begin(),key.end(),',',' ');istringstream hs(h),ks(key);vector<int>holes(m);for(int&x:holes)hs>>x;for(int&x:O)ks>>x;d.clear();for(auto&ct:cipher){vector<int>sh;for(int i=0;i<ct.size();i++)sh.push_back((coord[holes[i%m]]-coord[holes[0]]+(holes[i%m]<holes[0]?179:0)+179*(i/m))%26);d.push_back(sh);}
auto v=project(O);mt19937 rng(52770121);float best=-1e30;array<int,26>bp;for(int r=0;r<4;r++){for(int i=0;i<26;i++)P[i]=i;shuffle(P.begin(),P.end(),rng);float now=score(P,v);for(int it=0;it<15000;it++){auto pp=P;int a=rng()%26,b=rng()%26;swap(pp[a],pp[b]);float next=score(pp,v),temp=.2+12*(1.-(it%5000)/5000.);if(next>=now||log((rng()+1.)/4294967297.)<(next-now)/temp){P=pp;now=next;if(now>best){best=now;bp=P;}}}}cout<<number++<<' '<<prof<<'\n';emit(best,bp,O);cout<<flush;}}
